process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='', AKC='';
const DEP=Buffer.from('','base64').toString();
async function jsonSafe(r){ const t=await r.text();
  const a=t.indexOf('['), o=t.indexOf('{');
  const i=(a>=0&&(a<o||o<0))?a:o; if(i<0) return null;
  try{ return JSON.parse(t.slice(i)); }catch(e){ return null; } }
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'g4', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'g4');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await jsonSafe(r)||{};
}
async function off(id){ if(!id) return; await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'G4'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await jsonSafe(r);
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  for(const [opt,val] of [['ps_uxd_kat',KAT],['ps_uxd_akc',AKC]]){
    const s=await snip('TEMP g4 '+opt, "update_option('"+opt+"','"+val+"','no');");
    await pause(1800); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  }
  const sd=await snip('TEMP g4 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_g4_dep=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.deploy=await jsonSafe(resp);
  await pause(1500);
  resp=await fetch(`${WP}/?ps_g4_test=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.pasibaigusi=await jsonSafe(resp);

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(15000);
  const eik=async(u)=>{ try{ await page.goto(u,{waitUntil:'networkidle',timeout:45000}); return true; }catch(e){ return String(e).slice(0,60); } };

  await eik(`${WP}/?ps_uxlog2=1&k=dq7m3z`);
  await pause(3000);
  out.rail=await page.evaluate(()=>Array.prototype.map.call(
    document.querySelectorAll('.pskat-rail a, .pskat-rail h3'), a=>a.textContent.replace(/\s+/g,' ').trim()));
  out.juosta=await page.evaluate(()=>{
    const j=document.querySelector('.pskat-laikot');
    return j?{mygtukai:Array.prototype.map.call(j.querySelectorAll('.lg'),x=>x.textContent.trim()),
      aktyvus:(j.querySelector('.lg.on')||{}).textContent,
      akcijos_mygtukas:(j.querySelector('.lg-akcija')||{}).textContent,
      akcijos_url:(j.querySelector('.lg-akcija')||{}).getAttribute('href')}:null;
  });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/g4_arteja.png', png.toString('base64'),'g4');

  /* Pasibaige */
  await eik(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&view=gi_pasibaige`);
  await pause(2000);
  out.pasibaige_ekranas=await page.evaluate(()=>({
    eiluciu:document.querySelectorAll('.pskat-t tbody tr').length,
    pirma:(document.querySelector('.pskat-t tbody tr')||{}).innerText.replace(/\n+/g,' | ').slice(0,160),
    akcijos_mygtukas:!!document.querySelector('.lg-akcija'),
    pastaba:(document.querySelector('.pskat-laikot .pat2')||{}).textContent}));
  png=await page.screenshot(); out.s2=await putRaw('screenshots/g4_pasibaige.png', png.toString('base64'),'g4');

  /* Riba 180 */
  await eik(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&view=gi_kritine&gi=180`);
  await pause(2000);
  out.riba180=await page.evaluate(()=>({
    rail:Array.prototype.map.call(document.querySelectorAll('.pskat-rail a[href*="gi_"]'),
      a=>a.textContent.replace(/\s+/g,' ').trim()),
    aktyvus:(document.querySelector('.pskat-laikot .lg.on')||{}).textContent,
    eiluciu:document.querySelectorAll('.pskat-t tbody tr').length}));

  /* Kelias i akcija */
  await eik(`${WP}/wp-admin/admin.php?page=ps-akcijos&nauja=1&gi=90`);
  await pause(2500);
  out.akcija=await page.evaluate(()=>({
    pav:(document.querySelector('.f-pav')||{}).value,
    tabas:(document.querySelector('.tb.on')||{}).textContent,
    dienu:(document.querySelector('.f-gi-dienu')||{}).value,
    nuo:(document.querySelector('.f-nuo')||{}).value,
    iki:(document.querySelector('.f-iki')||{}).value}));
  png=await page.screenshot(); out.s3=await putRaw('screenshots/g4_akcija.png', png.toString('base64'),'g4');

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await jsonSafe(r);
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/g4.json', out);
}
main().catch(async e=>{ await putJson('analize/g4.json',{klaida:String(e).slice(0,400)}); });
